# A deterministic squarified layout. Fixtures are invented, not scanned from disk.
def layout(nodes,x,y,w,h):
    total=sum(n['size'] for n in nodes)
    work=[(n,n['size']/total*w*h) for n in sorted(nodes,key=lambda n:-n['size'])]
    result=[]
    def worst(row,side):
        if not row:return float('inf')
        vals=[a for _,a in row];s=sum(vals)
        return max(side*side*max(vals)/(s*s),s*s/(side*side*min(vals)))
    while work:
        side=min(w,h);row=[]
        while work and worst(row+[work[0]],side)<=worst(row,side):row.append(work.pop(0))
        area=sum(a for _,a in row)
        if w>=h:
            rw=area/h;cy=y
            for n,a in row:
                rh=a/rw;result.append((n,x,cy,rw,rh));cy+=rh
            x+=rw;w-=rw
        else:
            rh=area/w;cx=x
            for n,a in row:
                rw=a/rh;result.append((n,cx,y,rw,rh));cx+=rw
            y+=rh;h-=rh
    return result

def tree(nodes,w=820,h=495,depth=0):
    out=''
    for n,x,y,bw,bh in layout(nodes,0,0,w,h):
        cls='tile '+n['kind']+(' haschildren' if n['children'] else '')+(' selected' if n['name']=='Build cache' else '')+(' diskimages' if n['name']=='Disk images' else '')
        style=f'left:{x/w*100:.4f}%;top:{y/h*100:.4f}%;width:{bw/w*100:.4f}%;height:{bh/h*100:.4f}%;'
        label=escape(n['name']);size=n['size']
        out+=f'<div class="{cls}" style="{style}"><div class="tilelabel"><span>{label}</span><small>{size} GiB</small></div>'
        if n['children'] and depth<2 and bw>110 and bh>92:
            out+='<div class="children">'+tree(n['children'],bw-8,bh-32,depth+1)+'</div>'
        elif bw>100 and bh>125:
            out+=f'<div class="tilevalue">{size}<small> GiB</small></div>'
        out+='</div>'
    return out

def mapbox(nodes=DATA,extra='',w=820,h=495):return f'<div class="treemap {extra}">'+tree(nodes,w,h)+'</div>'
